/* Lantern standalone CRM example. Fictional data; browser storage only. */
(() => {
'use strict';
const KEY='lantern.crm.public.v1', PREF='lantern.crm.preferences.v1';
const now=new Date(), iso=(days,h=11)=>{const d=new Date(now);d.setDate(d.getDate()+days);d.setHours(h,0,0,0);return d.toISOString()};
const seed={mode:'showcase',users:[{id:'central',name:'Aditi Rao',role:'central_manager',branches:['north','west'],active:true,can_admin:true},{id:'manager',name:'Kabir Mehta',role:'branch_manager',branches:['north'],active:true,can_admin:false},{id:'sales-a',name:'Neha Singh',role:'salesperson',branches:['north'],active:true,can_admin:false},{id:'sales-b',name:'Rohan Verma',role:'salesperson',branches:['west'],active:true,can_admin:false}],branches:[{id:'north',name:'North desk · DEMO'},{id:'west',name:'West desk · DEMO'}],config:{stages:[{id:'new',label:'New enquiry',color:'#6b8799'},{id:'contacted',label:'Contacted',color:'#247fad'},{id:'qualified',label:'Qualified',color:'#2f806c'},{id:'survey',label:'Site survey',color:'#8b68a1'},{id:'quoted',label:'Quotation',color:'#ae771e'},{id:'won',label:'Booked',color:'#3d8720'},{id:'lost',label:'Closed lost',color:'#a66060'}],fields:[],brand:{name:'Lantern CRM',primary:'#112b50',accent:'#ffa276'},ai_enabled:true,monthly_budget:0},leads:[]};
const names=['Arjun Malhotra','Mira Kapoor','Northstar Packaging','Dev Sharma','Asha Batra','Cedar Learning Centre','Vikram Sethi','Ritu Anand','Blueleaf Foods','Anil Tandon','Kavya Suri','Maple Components','Sahil Chopra','Pooja Khanna','Harbour Warehousing','Nitin Arora','Meera Dutt','Juniper Textiles','Rahul Bhasin','Sana Jain','Oakwell Clinic'];
const stageIds=['survey','new','quoted','contacted','qualified','survey','new','won','qualified','contacted','quoted','lost','new','survey','quoted','qualified','contacted','new','won','contacted','survey'];
const actions=['Confirm roof access for site visit','First call to understand requirement','Review quotation with decision-maker','Request latest electricity bill','Confirm property ownership','Agree a survey slot','Call after 4 PM'];
names.forEach((name,i)=>{const commercial=i%3===2,b=i%2?'west':'north';seed.leads.push({id:`DEMO-${String(i+1).padStart(3,'0')}`,name,email:`enquiry${i+1}@example.com`,phone:`DEMO-PHONE-${String(i+1).padStart(3,'0')}`,company:commercial?name:'',segment:commercial?'Commercial':'Residential',branch_id:b,assigned_user_id:b==='north'?'sales-a':'sales-b',stage_id:stageIds[i],source:['Facebook · sample','Referral · sample','Website · sample'][i%3],created_at:iso(-i-1),updated_at:iso(-i%4),version:1,property:{city:i%2?'Meerut':'Gurugram',address:`Fictional site ${i+1} · address pending`,bill:i%4===0?null:commercial?42000+i*800:4200+i*200,roof_area:i%3===0?null:commercial?240:65,capacity_kw:i%4===0?null:commercial?30:5},notes:commercial?'Exploring rooftop solar for daytime operations. Confirm sanctioned load and roof rights.':'Interested in rooftop solar. Bill and roof suitability need confirmation.',next_action_at:['won','lost'].includes(stageIds[i])?null:iso((i%6)-2,11+i%5),next_action:actions[i%actions.length],quote_value:stageIds[i]==='quoted'||stageIds[i]==='won'?(commercial?1450000:290000):null,custom:{},history:[{id:`h-${i}`,type:'intake',at:iso(-i-1),by:'Demo import',text:'Fictional enquiry added from sample intake. No live channel connected.'}],ai_drafts:[]})});
// Two fictional intake examples awaiting assignment; no staff or records added.
for(const id of ['DEMO-007','DEMO-018']){const l=seed.leads.find(l=>l.id===id);l.assigned_user_id=null;l.next_action='Assign an owner and confirm the requirement';l.next_action_at=null;}
window.LANTERN_CRM_SEED=structuredClone(seed);
let db, data, page='overview',selected=null,busy=false,search='',branch='',stage='', prefs={compact:false,view:null},storageWarning='';
try{prefs={...prefs,...JSON.parse(localStorage.getItem(PREF)||'null')}}catch{}
try{db=JSON.parse(localStorage.getItem(KEY)||'null')||structuredClone(seed);if(!Array.isArray(db.leads)||!db.config)throw Error('Invalid saved data')}catch{db=structuredClone(seed);storageWarning='Saved demo data could not be read. A fresh fictional dataset is in use.'}
let actorId=db.actorId||'central';
let pipelineStage='',workTab='today',mobileDetail=false,tableMode=false,ownerFilter='';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)],esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initials=n=>String(n||'?').split(/\s+/).slice(0,2).map(x=>x[0]).join('');
const money=v=>v==null?'Not recorded':new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(v);
const date=v=>v?new Date(v).toLocaleDateString('en-IN',{day:'numeric',month:'short'}):'Not scheduled';
const datetime=v=>v?new Date(v).toLocaleString('en-IN',{day:'numeric',month:'short',hour:'numeric',minute:'2-digit'}):'Not scheduled';
const localDate=v=>{if(!v)return '';const d=new Date(v);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)};
const stageOf=l=>data.config.stages.find(s=>s.id===l.stage_id)||{label:'Unknown stage',color:'#6b8799'};
const userName=id=>data.users.find(u=>u.id===id)?.name||'Unassigned';
const branchName=id=>data.branches.find(b=>b.id===id)?.name||'Unknown location';
const manager=()=>['central_manager','branch_manager'].includes(data.user.role);
const admin=()=>!!data.user.can_admin;
const overdue=l=>l.next_action_at&&new Date(l.next_action_at)<new Date()&&!['won','lost'].includes(l.stage_id);
const canSee=(u,l)=>u?.active!==false&&(u.role==='central_manager'||((u.branches||[]).includes(l.branch_id)&&(u.role==='branch_manager'||l.assigned_user_id===u.id)));
const storageIssues={data:false,preferences:false};
function writeStorage(kind,key,value){let saved=true;try{localStorage.setItem(key,JSON.stringify(value));storageIssues[kind]=false}catch{storageIssues[kind]=true;saved=false}storageWarning=Object.values(storageIssues).some(Boolean)?'Browser storage is unavailable. Changes and preferences affected by this failure are kept for this session only; they may be lost when you close or reload. Retry the change after enabling browser storage.':'';const notice=$('#storage-notice');if(notice){notice.textContent=storageWarning;notice.hidden=!storageWarning}return saved}
function persist(){db.actorId=actorId;return writeStorage('data',KEY,db)}
function savePrefs(){return writeStorage('preferences',PREF,prefs)}
function snapshot(){const u=db.users.find(u=>u.id===actorId&&u.active!==false)||db.users[0];return {...structuredClone(db),user:structuredClone(u),leads:structuredClone(db.leads.filter(l=>canSee(u,l))),mode:'showcase'}}
function event(l,type,text){l.history=l.history||[];l.history.unshift({id:`evt-${Date.now()}-${Math.random().toString(16).slice(2)}`,type,text,by:data.user.name,at:new Date().toISOString()});l.version=(l.version||0)+1;l.updated_at=new Date().toISOString()}
async function api(method,args={}){
 if(method==='bootstrap')return snapshot();
 const u=db.users.find(u=>u.id===actorId),l=args.lead_id&&db.leads.find(x=>x.id===args.lead_id);
 if(args.lead_id&&(!l||!canSee(u,l)))throw Error('This demo view cannot access this enquiry.');
 if(l&&l.version!==args.version)throw Error('This enquiry changed. Reopen it and try again.');
 if(method==='save_lead'){const allowed=['stage_id','notes','property','next_action_at','next_action','custom','quote_value'];if(Object.keys(args.changes).some(k=>!allowed.includes(k)))throw Error('Use Transfer ownership to change assignment.');if(args.changes.stage_id&&!db.config.stages.some(s=>s.id===args.changes.stage_id))throw Error('Choose a valid stage.');Object.assign(l,structuredClone(args.changes));event(l,'update',args.changes.stage_id?'Stage updated to '+db.config.stages.find(s=>s.id===l.stage_id).label:'Requirement and enquiry details updated.');}
 else if(method==='assign_lead'){const target=db.users.find(t=>t.id===args.assigned_user_id);if(!manager()||!target||target.active===false||target.role!=='salesperson'||!target.branches.includes(args.branch_id)||(u.role!=='central_manager'&&!u.branches.includes(args.branch_id)))throw Error('Choose an active salesperson in a location you manage.');if(!args.reason?.trim())throw Error('Add a reason for this transfer.');const old=userName(l.assigned_user_id);l.assigned_user_id=target.id;l.branch_id=args.branch_id;event(l,'assignment',`${old} → ${target.name}. ${args.reason}`)}
 else if(method==='add_activity'){if(!args.text?.trim())throw Error('Add a note before saving.');if('next_action' in args)l.next_action=args.next_action;if('next_action_at' in args)l.next_action_at=args.next_action_at;event(l,args.type,args.text)}
 else if(method==='save_settings'){if(!u.can_admin)throw Error('Settings administration is required.');db.config=structuredClone(args.config)}
 else if(method==='create_user'){if(!u.can_admin)throw Error('Settings administration is required.');const v=args.user||args;if(!v.name?.trim()||!v.branches?.length)throw Error('Name and location are required.');db.users.push({id:`demo-user-${Date.now()}`,name:v.name,role:v.role||'salesperson',branches:v.branches,active:true,can_admin:false})}
 else if(method==='import_rows'){if(!manager())throw Error('A manager imports sample enquiries.');db.importKeys=db.importKeys||[];let added=0;for(const row of args.rows){const key=JSON.stringify([row.source,row.account_id,row.form_id,row.submission_id]);if(db.importKeys.includes(key))continue;if(u.role!=='central_manager'&&!u.branches.includes(row.branch_id))throw Error('This import contains an inaccessible location.');db.leads.push({...structuredClone(row),id:`DEMO-IMPORT-${db.leads.length+1}`,version:1,created_at:new Date().toISOString(),updated_at:new Date().toISOString(),history:[{id:`import-${Date.now()}`,type:'intake',by:u.name,at:new Date().toISOString(),text:'Imported fictional sample; source identity preserved.'}],ai_drafts:[]});db.importKeys.push(key);added++}toast(`${added} added · ${args.rows.length-added} already received`)}
 persist();return snapshot();
}
async function mutate(method,args,message){
 if(busy)return false;busy=true;$$('button[type=submit]').forEach(b=>b.disabled=true);const recordScroll=$('#record-workspace')?.scrollTop||0;
 try{data=await api(method,args);if(selected&&!data.leads.some(l=>l.id===selected))selected=null;render();if($('#record-workspace'))$('#record-workspace').scrollTop=recordScroll;if(storageIssues.data)toast('Change applied for this session only. Browser storage could not save it.');else if(message)toast(message);return true}
 catch(e){toast(e.message);return false}
 finally{busy=false;$$('button[type=submit]').forEach(b=>b.disabled=false)}
}
let toastTimer;function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5000)}
function icon(name){const paths={overview:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',enquiries:'<path d="M8 4h12v16H4V8z"/><path d="M8 4v4H4m4 5h8m-8 4h6"/>',pipeline:'<rect x="3" y="4" width="5" height="16" rx="1"/><rect x="10" y="4" width="5" height="11" rx="1"/><rect x="17" y="4" width="4" height="7" rx="1"/>',work:'<rect x="4" y="5" width="16" height="16" rx="2"/><path d="M8 3v4m8-4v4M4 11h16m-12 5 2 2 5-5"/>',team:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m2-16a3 3 0 0 1 0 6m1 3a5 5 0 0 1 3 4v3"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="var(--nav)"/><circle cx="15" cy="17" r="3" fill="var(--nav)"/>'};return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.enquiries}</svg>`}
const nav=[['overview','Overview'],['enquiries','Enquiries'],['pipeline','Pipeline'],['work','My Work'],['team','Team & locations'],['settings','Settings']];
function filtered(){return data.leads.filter(l=>(!branch||l.branch_id===branch)&&(!stage||l.stage_id===stage)&&(!search||[l.name,l.company,l.email,l.id,l.property?.city].join(' ').toLowerCase().includes(search.toLowerCase())))}
function badge(l){return `<span class="badge"><span class="dot" style="background:${safeColor(stageOf(l).color)};margin:0"></span>${esc(stageOf(l).label)}</span>`}
function safeColor(c){return /^#[0-9a-f]{6}$/i.test(c||'')?c:'#073b5c'}
function leadButton(l){return `<button class="link-button" data-lead="${esc(l.id)}">${esc(l.name)}</button>`}
function toolbar(){return `<div class="toolbar"><div class="filters"><input class="search" id="search" aria-label="Search enquiries" placeholder="Search name, city or enquiry ID…" value="${esc(search)}"><select id="branch-filter" aria-label="Filter location"><option value="">All permitted locations</option>${data.branches.map(b=>`<option value="${esc(b.id)}" ${branch===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select><select id="stage-filter" aria-label="Filter stage"><option value="">All stages</option>${data.config.stages.map(s=>`<option value="${esc(s.id)}" ${stage===s.id?'selected':''}>${esc(s.label)}</option>`).join('')}</select></div><button id="save-view">Save view</button></div>`}
function table(leads,short=false){return `<div class="table-wrap"><table class="${prefs.compact?'compact':''}"><thead><tr><th>Enquiry</th><th>Stage</th><th>Location</th>${short?'':'<th>Owner</th><th>System size</th>'}<th>Next action</th></tr></thead><tbody>${leads.map(l=>`<tr><td><div class="person"><span class="avatar">${esc(initials(l.name))}</span><div>${leadButton(l)}<small>${esc(l.segment)} · ${esc(l.property?.city||'City unknown')}</small></div></div></td><td>${badge(l)}</td><td>${esc(branchName(l.branch_id).replace(' · DEMO',''))}</td>${short?'':`<td>${esc(userName(l.assigned_user_id))}</td><td>${l.property?.capacity_kw!=null?esc(l.property.capacity_kw)+' kW':'<span class="muted">Unknown</span>'}</td>`}<td><span class="${overdue(l)?'due':'muted'}">${date(l.next_action_at)}</span><div class="activity-pill">${esc(l.next_action||'No next action').slice(0,44)}</div></td></tr>`).join('')}</tbody></table>${leads.length?'':'<div class="empty"><h3>No enquiries match this view</h3><p>Clear a filter or try another name. Visibility follows the selected account.</p></div>'}</div>`}
function taskRows(leads){return leads.map(l=>`<div class="task-row"><span class="avatar">${esc(initials(l.name))}</span><div class="body">${leadButton(l)}<p>${esc(l.next_action||'Set the next action')}</p><div class="activity-pill">${esc(userName(l.assigned_user_id))}</div></div><span class="due ${overdue(l)?'':'future'}">${date(l.next_action_at)}</span></div>`).join('')||'<div class="empty"><h3>No scheduled follow-ups</h3><p>Open an enquiry to plan its next action.</p></div>'}
const isSales=()=>data.user.role==='salesperson';
const isOpen=l=>!['won','lost'].includes(l.stage_id);
const endOfToday=()=>{const d=new Date();d.setHours(23,59,59,999);return d};
const activityTypes=new Set(['call_connected','call_no_answer','site_visit','note']);
function priority(l){return !l.assigned_user_id?0:overdue(l)?1:!l.next_action||!l.next_action_at?2:3}
function prioritise(rows){return [...rows].sort((a,b)=>priority(a)-priority(b)||(a.next_action_at||'9999').localeCompare(b.next_action_at||'9999')||a.id.localeCompare(b.id))}
function reason(l){if(!l.assigned_user_id)return 'Owner needed';if(overdue(l))return 'Follow-up overdue';if(!l.next_action||!l.next_action_at)return 'Next action needed';return `Next: ${datetime(l.next_action_at)}`}
function evidence(l){const out=[];if(l.property?.bill==null)out.push('Electricity bill unknown');if(l.property?.roof_area==null)out.push('Roof area unknown');if(l.property?.capacity_kw==null)out.push('Capacity unconfirmed');if(l.stage_id==='survey'&&!(l.history||[]).some(h=>h.type==='site_visit'))out.push('No site-visit note recorded');if(l.stage_id==='quoted'&&l.quote_value==null)out.push('Quotation value missing');return out}
function defaultPage(){return isSales()?'work':'overview'}
function roleLabel(){return isSales()?'Sales workspace':data.user.role==='branch_manager'?'Branch coordination':'Business oversight'}
function navigation(){return nav.filter(([id])=>id!=='overview'||!isSales()).map(([id,label])=>[id,id==='overview'?(data.user.role==='branch_manager'?'Branch overview':'Business overview'):id==='work'?(isSales()?'My Work':'Team work'):label])}
function workspaceReset(){page=defaultPage();selected=null;search='';branch='';stage='';pipelineStage='';workTab='today';mobileDetail=false;tableMode=false;ownerFilter='';clearTimeout(toastTimer);$('#toast').classList.remove('show')}
function managementRows(rows,assignment=false){return prioritise(rows).map(l=>`<div class="decision-row"><div class="decision-person"><span class="avatar">${esc(initials(l.name))}</span><div>${leadButton(l)}<p>${esc(reason(l))} · ${esc(branchName(l.branch_id).replace(' · DEMO',''))}</p></div></div><div class="decision-next"><span>${esc(l.next_action||'No next action recorded')}</span><small>${esc(userName(l.assigned_user_id))} · ${esc(stageOf(l).label)}</small></div>${assignment&&!l.assigned_user_id?`<button data-assign="${esc(l.id)}">Assign owner</button>`:`<button data-lead="${esc(l.id)}">Review</button>`}</div>`).join('')||'<div class="empty"><h3>No outstanding items in this group</h3><p>New unassigned intake and missing next actions will appear here.</p></div>'}
function overview(){
 const rows=data.leads,open=rows.filter(isOpen),unassigned=open.filter(l=>!l.assigned_user_id),due=open.filter(overdue),central=data.user.role==='central_manager';
 if(!central)return managerOverview(open,unassigned,due);
 const exceptions=prioritise(open.filter(l=>!l.assigned_user_id||overdue(l)||!l.next_action_at||!l.next_action));
 return `<div class="page-head"><div><h1>Business oversight</h1><p class="muted">${esc(data.user.name)}’s view of ownership, follow-through and location decisions. Fictional operating data.</p></div><div class="actions"><button data-page="team">Inspect team</button><button data-page="settings" class="primary">Configure workspace</button></div></div><div class="role-summary"><span><strong>${open.length}</strong> open enquiries</span><span><strong>${unassigned.length}</strong> without an owner</span><span><strong>${due.length}</strong> overdue follow-ups</span><span><strong>${open.filter(l=>l.stage_id==='quoted').length}</strong> awaiting quotation follow-through</span></div><section class="panel flush"><div class="toolbar"><h2>Locations at a glance</h2><span class="muted">Current state · not conversion or staff performance</span></div><div class="table-wrap"><table class="location-table"><thead><tr><th>Handling location</th><th>Open</th><th>Unassigned</th><th>Overdue</th><th>${esc(data.config.stages.find(s=>s.id==='survey')?.label||'Survey')}</th><th>Quoted value</th><th></th></tr></thead><tbody>${data.branches.map(b=>{const ls=open.filter(l=>l.branch_id===b.id);return `<tr><td><strong>${esc(b.name)}</strong><small class="location-caption">Illustrative sales desk</small></td><td>${ls.length}</td><td>${ls.filter(l=>!l.assigned_user_id).length}</td><td>${ls.filter(overdue).length}</td><td>${ls.filter(l=>l.stage_id==='survey').length}</td><td>${money(ls.filter(l=>l.stage_id==='quoted').reduce((sum,l)=>sum+(Number(l.quote_value)||0),0))}</td><td><button data-location="${esc(b.id)}">Review location</button></td></tr>`}).join('')}</tbody></table></div><div class="table-foot">Quotation amounts are recorded estimates, not revenue. Actual branch structure remains unconfirmed.</div></section><section class="panel"><div class="section-title"><div><h2>Decisions & exceptions</h2><p class="muted section-description">Unassigned first, then overdue work and missing next actions.</p></div><span class="badge orange">${exceptions.length} to review</span></div>${managementRows(exceptions.slice(0,7),true)}</section><section class="panel"><div class="section-title"><h2>Quotations needing a conversation</h2><button class="link-button" data-pipeline-stage="quoted">Open quotation stage</button></div>${managementRows(open.filter(l=>l.stage_id==='quoted'))}</section>`;
}
function managerOverview(open,unassigned,due){
 const reps=data.users.filter(u=>u.role==='salesperson'&&u.active!==false&&u.branches.some(b=>data.user.branches.includes(b)));
 return `<div class="page-head"><div><h1>Branch coordination</h1><p class="muted">${esc(data.user.name)} · ${data.user.branches.map(b=>esc(branchName(b))).join(', ')}. Give every next step an owner.</p></div><button id="import">Import sample intake</button></div><div class="role-summary"><span><strong>${unassigned.length}</strong> awaiting assignment</span><span><strong>${due.length}</strong> overdue follow-ups</span><span><strong>${open.filter(l=>['survey','quoted'].includes(l.stage_id)).length}</strong> survey / quotation handoffs</span></div><section class="panel"><div class="section-title"><div><h2>Assign incoming enquiries</h2><p class="muted section-description">Only active salespeople in a location you manage can receive these.</p></div><span class="badge orange">${unassigned.length} unassigned</span></div>${managementRows(unassigned,true)}</section><section class="panel"><div class="section-title"><h2>Work distribution</h2><button class="link-button" data-page="team">Team details</button></div><div class="owner-distribution">${reps.map(u=>{const ls=open.filter(l=>l.assigned_user_id===u.id);return `<div class="owner-line"><div class="person"><span class="avatar">${esc(initials(u.name))}</span><div><strong>${esc(u.name)}</strong><small class="location-caption">${u.branches.map(b=>esc(branchName(b).replace(' · DEMO',''))).join(', ')}</small></div></div><span><strong>${ls.length}</strong> open</span><span class="${ls.some(overdue)?'due':'muted'}">${ls.filter(overdue).length} overdue</span><button data-owner-queue="${esc(u.id)}">Review work</button></div>`}).join('')}</div></section><div class="coordination-grid"><section class="panel"><div class="section-title"><h2>Follow-ups to unblock</h2></div>${managementRows(due)}</section><section class="panel"><div class="section-title"><h2>Survey & quotation handoffs</h2></div>${managementRows(open.filter(l=>['survey','quoted'].includes(l.stage_id)))}</section></div>`;
}
function queueMarkup(rows,emptyText='Try another filter or choose a different work group.'){
 return `<div class="queue-list" aria-label="Enquiry queue">${rows.map(l=>`<button class="queue-item ${selected===l.id?'selected':''}" data-lead="${esc(l.id)}" ${selected===l.id?'aria-current="true"':''}><span class="queue-top"><strong>${esc(l.name)}</strong><span class="${overdue(l)?'due':'muted'}">${l.next_action_at?date(l.next_action_at):'Unscheduled'}</span></span><span class="queue-sub">${esc(l.segment)} · ${esc(l.property?.city||'City unknown')}</span><span class="queue-action">${esc(l.next_action||'Set the next action')}</span><span class="queue-bottom">${badge(l)}<span>${esc(!l.assigned_user_id?'Owner needed':userName(l.assigned_user_id))}</span></span></button>`).join('')||`<div class="empty"><h3>No enquiries in this queue</h3><p>${esc(emptyText)}</p></div>`}</div>`;
}
function splitWorkspace(rows,label,extra=''){
 if(!rows.some(l=>l.id===selected))selected=rows[0]?.id||null;
 return `<div class="split-workspace ${mobileDetail?'detail-active':''}"><section class="queue-pane"><div class="queue-heading"><h2>${esc(label)}</h2><span class="badge">${rows.length}</span></div>${extra}${queueMarkup(rows)}</section><section id="record-workspace" class="record-pane" aria-label="Selected enquiry workspace">${selected?'':'<div class="empty"><h3>Select an enquiry to work on</h3><p>Its requirement, next action and activity history will stay alongside the queue.</p></div>'}</section></div>`;
}
function enquiries(){let rows=prioritise(filtered().filter(l=>!ownerFilter||l.assigned_user_id===ownerFilter));return `<div class="page-head"><div><h1>Enquiry workspace</h1><p class="muted">Select a conversation. Keep its next step, requirement and history in view.</p></div><div class="actions">${manager()?'<button id="import">Import sample</button>':''}<button id="toggle-table">${tableMode?'Split workspace':'Table utility'}</button></div></div><section class="panel flush workspace-filters">${toolbar()}${ownerFilter?`<div class="table-foot">Owner: ${esc(userName(ownerFilter))} <button class="link-button" id="clear-owner">Clear owner filter</button></div>`:''}</section>${tableMode?`<section class="panel flush">${table(rows)}<div class="table-foot">${rows.length} permitted enquiries. Select a name to return to its working detail.</div></section>`:splitWorkspace(rows,'Enquiries')}`}
function pipeline(){if(!data.config.stages.some(s=>s.id===pipelineStage))pipelineStage=data.config.stages[0]?.id||'';const s=data.config.stages.find(s=>s.id===pipelineStage),rows=prioritise(data.leads.filter(l=>l.stage_id===pipelineStage&&(!branch||l.branch_id===branch)));return `<div class="page-head"><div><h1>Pipeline review</h1><p class="muted">Choose a stage, review the record and decide its next step. Stage alone is not evidence of completed work.</p></div><div class="actions"><select id="pipeline-branch" aria-label="Pipeline location"><option value="">All permitted locations</option>${data.branches.filter(b=>data.user.role==='central_manager'||data.user.branches.includes(b.id)).map(b=>`<option value="${esc(b.id)}" ${branch===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select><button data-page="enquiries">All enquiries</button></div></div><div class="stage-flow" aria-label="Select pipeline stage">${data.config.stages.map(s=>`<button class="stage-step ${s.id===pipelineStage?'active':''}" data-stage="${esc(s.id)}" aria-pressed="${s.id===pipelineStage}"><span><span class="dot" style="background:${safeColor(s.color)}"></span>${esc(s.label)}</span><strong>${data.leads.filter(l=>l.stage_id===s.id&&(!branch||l.branch_id===branch)).length}</strong></button>`).join('')}</div><div class="pipeline-context"><span><strong>${esc(s?.label)}</strong> · ${rows.length} current enquiries</span><span>${rows.filter(l=>!l.next_action||!l.next_action_at).length} without a scheduled next step · ${rows.filter(l=>evidence(l).length).length} with information to confirm</span></div>${splitWorkspace(rows,s?.label||'Stage')}`}
function workGroups(){const rows=data.leads.filter(l=>isOpen(l)&&(isSales()?l.assigned_user_id===data.user.id:true)),end=endOfToday();return {today:prioritise(rows.filter(l=>!l.next_action_at||new Date(l.next_action_at)<=end)),upcoming:prioritise(rows.filter(l=>l.next_action_at&&new Date(l.next_action_at)>end)),completed:data.leads.flatMap(l=>(l.history||[]).filter(h=>activityTypes.has(h.type)&&(!isSales()||h.by===data.user.name||h.by===data.user.id)).map(h=>({lead:l,event:h}))).sort((a,b)=>b.event.at.localeCompare(a.event.at))}}
function work(){const groups=workGroups(),rows=workTab==='completed'?[...new Map(groups.completed.map(x=>[x.lead.id,x.lead])).values()]:groups[workTab];return `<div class="page-head"><div><h1>${isSales()?'My working day':'Team work'}</h1><p class="muted">${isSales()?esc(data.user.name)+' · ':''}${isSales()?data.user.branches.map(b=>esc(branchName(b))).join(', '):'Your permitted team'} · Prioritised by due time and recorded next action.</p></div><button data-page="enquiries">Browse enquiries</button></div><div class="work-tabs" role="tablist" aria-label="Work groups">${[['today','Today & overdue'],['upcoming','Upcoming'],['completed','Completed activity']].map(([id,label])=>`<button role="tab" aria-selected="${workTab===id}" data-work-tab="${id}">${label}<span>${groups[id].length}</span></button>`).join('')}</div><p class="work-explanation">${workTab==='today'?'Overdue first, then work due today or still needing a scheduled next step. Closed enquiries stay out of this queue.':workTab==='upcoming'?'Future follow-ups with a recorded date. Logging a call can move its next action here.':'Recorded calls, site-visit notes and internal notes—not a count of won sales or completed installations.'}</p>${workTab==='completed'?`<section class="panel completed-events"><h2>Recorded activity</h2>${groups.completed.slice(0,8).map(({lead:l,event:h})=>`<div class="completed-event">${leadButton(l)}<p>${esc(h.text)}</p><small>${esc(h.type.replaceAll('_',' '))} · ${esc(h.by)} · ${datetime(h.at)}</small></div>`).join('')||'<p class="muted section-description">No completed activity recorded by this account yet. Log an outcome from the working queue to begin.</p>'}</section>`:''}${splitWorkspace(rows,workTab==='completed'?'Activity enquiries':workTab==='upcoming'?'Upcoming follow-ups':'Work next')}`}

function team(){const users=data.users.filter(u=>data.user.role==='central_manager'||u.id===data.user.id||u.branches.some(b=>data.user.branches.includes(b)));return `<div class="page-head"><div><h1>Team & locations</h1><p class="muted">Illustrative responsibilities. Your actual team structure would be agreed before implementation.</p></div>${admin()?'<button id="add-user" class="primary">Add demo user</button>':''}</div><section class="panel flush"><div class="toolbar"><h2>Workspace users</h2><span class="muted">${users.length} visible</span></div><div class="table-wrap"><table><thead><tr><th>Person</th><th>Role</th><th>Locations</th><th>Assigned enquiries</th><th>Status</th></tr></thead><tbody>${users.map(u=>`<tr><td><div class="person"><span class="avatar">${esc(initials(u.name))}</span><strong>${esc(u.name)}</strong></div></td><td>${esc(u.role.replaceAll('_',' '))}${u.can_admin?' + settings':''}</td><td>${u.branches.map(b=>esc(branchName(b))).join(', ')}</td><td>${data.leads.filter(l=>l.assigned_user_id===u.id).length}</td><td><span class="badge green">${u.active===false?'Inactive':'Active'}</span></td></tr>`).join('')}</tbody></table></div></section><section class="panel"><h2>Handling locations</h2>${data.branches.filter(b=>data.user.role==='central_manager'||data.user.branches.includes(b.id)).map(b=>`<div class="task-row"><div class="body"><strong>${esc(b.name)}</strong><p>Demonstration sales desk · illustrative, not an actual business branch</p></div><span class="badge">${data.leads.filter(l=>l.branch_id===b.id).length} enquiries</span></div>`).join('')}<p class="admin-note">Demo view switching illustrates scope; it is not authentication or a security boundary.</p></section>`}
function settings(){return `<div class="page-head"><div><h1>Settings</h1><p class="muted">Make the workspace fit the way your team works.</p></div></div><div class="settings-layout"><div><section class="panel"><h2>Pipeline stages</h2><p class="muted" style="font-size:12px;margin:8px 0 18px">Rename a stage without changing its history or record identity.</p><form id="stage-settings">${data.config.stages.map(s=>`<label class="stage-editor"><span>${esc(s.id)}</span><input name="${esc(s.id)}" value="${esc(s.label)}" required maxlength="45" ${admin()?'':'disabled'}></label>`).join('')}<div class="form-actions"><button class="primary" ${admin()?'':'disabled'}>Save stage names</button></div></form></section><section class="panel"><h2>Custom enquiry fields</h2><p class="muted" style="font-size:12px;margin:8px 0 15px">Fields appear on every enquiry. Values are saved per record.</p>${data.config.fields.map(f=>`<div class="field-chip"><span>${esc(f.label)}</span><span class="muted">${esc(f.type)}</span></div>`).join('')||'<p class="muted" style="font-size:12px">No custom fields yet. Try “Roof ownership”.</p>'}<form id="field-settings" class="form-grid" style="margin-top:17px"><label>Field label<input name="label" required maxlength="50" placeholder="Roof ownership" ${admin()?'':'disabled'}></label><label>Field type<select name="type" ${admin()?'':'disabled'}><option value="text">Text</option><option value="number">Number</option></select></label><div><button ${admin()?'':'disabled'}>Add field</button></div></form></section><section class="panel"><h2>Personal preferences</h2><label class="checkbox-label" style="margin-top:18px"><input type="checkbox" id="compact" ${prefs.compact?'checked':''}>Compact table rows</label><p class="muted" style="font-size:12px;margin-top:16px">${prefs.view?'Saved view: '+esc(prefs.view.name):'Save enquiry filters for this account in this browser.'}</p><div class="form-actions"><button id="restore-view" ${prefs.view?'':'disabled'}>Open saved view</button><button id="clear-view" ${prefs.view?'':'disabled'}>Clear saved view</button></div></section></div><div><section class="panel"><h2>Workspace appearance</h2><form id="brand-settings" style="margin-top:19px"><div class="form-grid"><label class="wide">Workspace name<input name="name" value="${esc(data.config.brand.name)}" required maxlength="40" ${admin()?'':'disabled'}></label><label>Primary colour<input type="color" name="primary" value="${safeColor(data.config.brand.primary)}" ${admin()?'':'disabled'}></label><label>Accent colour<input type="color" name="accent" value="${safeColor(data.config.brand.accent)}" ${admin()?'':'disabled'}></label></div><div class="form-actions"><button class="primary" ${admin()?'':'disabled'}>Apply appearance</button></div></form></section><section class="panel"><div class="section-title"><h2>AI assistance</h2><span class="badge orange">Demo · not connected</span></div><form id="ai-settings"><label class="checkbox-label"><input type="checkbox" name="enabled" ${data.config.ai_enabled?'checked':''} ${admin()?'':'disabled'}>Show AI demonstration tools</label><label style="margin-top:18px">Illustrative monthly budget (₹)<input name="budget" type="number" min="0" max="1000000" value="${Number(data.config.monthly_budget)||0}" ${admin()?'':'disabled'}></label><p class="muted" style="font-size:12px;margin-top:12px">0 means off. This records a proposed budget; no billing, API calls or provider connection exists.</p><div class="form-actions"><button ${admin()?'':'disabled'}>Save AI preferences</button></div></form></section><section class="panel"><h2>Connections</h2>${['Facebook lead intake','WhatsApp & calling','ERPNext','AI provider'].map(n=>`<div class="meta-row"><span>${n}</span><span class="muted">Not connected</span></div>`).join('')}</section><section class="panel"><h2>Reset the showcase</h2><p class="muted" style="font-size:12px;margin-top:10px">Restore the original fictional records and settings in this browser.</p><button id="reset" class="danger" style="margin-top:16px">Reset demo data</button></section>${!admin()?'<p class="notice">Global settings require the settings-admin capability. Personal preferences remain available.</p>':''}</div></div>`}
function render(){document.documentElement.style.setProperty('--primary',safeColor(data.config.brand.primary));document.documentElement.style.setProperty('--accent',safeColor(data.config.brand.accent));$('#app').innerHTML=`<div class="shell"><aside class="sidebar" id="sidebar"><div class="brand"><img src="/assets/brand/guiding-lantern-clear.svg" alt="" onerror="this.style.display='none'"><div>${esc(data.config.brand.name)}<small>${esc(roleLabel())}</small></div></div><nav class="nav" aria-label="Workspace">${navigation().map(([id,label])=>`<button data-page="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(id)}${label}</button>`).join('')}</nav><div class="sidebar-bottom"><button class="quiet" id="help">Showcase guide</button><p>Fictional data. Familiar workflow.<br>Configured around your business.</p></div></aside><div class="workspace"><header class="topbar"><button class="mobile-menu" id="menu" aria-label="Open navigation">Menu</button><div class="context">Workspace <span style="margin:0 12px;color:#9cabb4">/</span><strong>${navigation().find(x=>x[0]===page)?.[1]}</strong></div><span class="demo-pill">Fictional data · showcase</span><div class="user-control"><span class="avatar">${esc(initials(data.user.name))}</span><label>Demo view<select id="actor">${data.users.filter(u=>u.active!==false).map(u=>`<option value="${esc(u.id)}" ${u.id===data.user.id?'selected':''}>${esc(u.name)} · ${u.can_admin?'Admin':u.role==='branch_manager'?'Manager':u.role==='central_manager'?'Central':'Sales'}</option>`).join('')}</select></label></div></header><main id="main" tabindex="-1"><p id="storage-notice" class="notice" ${storageWarning?'':'hidden'}>${esc(storageWarning)}</p>${({overview,enquiries,pipeline,work,team,settings})[page]()}</main></div></div>`;bind();if(selected&&$('#record-workspace'))renderRecord(selected);}
function bind(){ $$('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;selected=null;mobileDetail=false;ownerFilter='';render()});$$('[data-lead]').forEach(b=>b.onclick=()=>openLead(b.dataset.lead));$('#menu')?.addEventListener('click',()=>$('#sidebar').classList.toggle('open'));$('#help').onclick=help;$('#actor')?.addEventListener('change',async e=>{actorId=e.target.value;persist();data=await api('bootstrap');prefs.view=prefs.views?.[data.user.id]||null;workspaceReset();ownerFilter='';render()});bindRoleWorkspace();$('#branch-filter')?.addEventListener('change',e=>{branch=e.target.value;render()});$('#stage-filter')?.addEventListener('change',e=>{stage=e.target.value;render()});$('#search')?.addEventListener('input',e=>{const position=e.target.selectionStart;search=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(position,position)});$('#save-view')?.addEventListener('click',()=>{prefs.view={name:'My enquiry view',branch,stage,search};prefs.views=prefs.views||{};prefs.views[data.user.id]=structuredClone(prefs.view);const saved=savePrefs();toast(saved?'View saved. Open it from Settings.':'View kept for this session only. Browser storage could not save it.');});$('#import')?.addEventListener('click',importDialog);$('#add-user')?.addEventListener('click',userDialog);$('#compact')?.addEventListener('change',e=>{prefs.compact=e.target.checked;const saved=savePrefs();toast(saved?'Table density saved':'Table density changed for this session only. Browser storage could not save it.')});$('#restore-view')?.addEventListener('click',()=>{({branch,stage,search}=prefs.view);ownerFilter='';selected=null;mobileDetail=false;page='enquiries';render()});$('#clear-view')?.addEventListener('click',()=>{prefs.view=null;if(prefs.views)delete prefs.views[data.user.id];const saved=savePrefs();render();toast(saved?'Saved view cleared':'View cleared for this session only. Browser storage could not save it.')});$('#reset')?.addEventListener('click',resetDialog);
 $('#stage-settings')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target),c=structuredClone(data.config);c.stages.forEach(s=>s.label=String(f.get(s.id)).trim());if(c.stages.some(s=>!s.label)||new Set(c.stages.map(s=>s.label.toLowerCase())).size!==c.stages.length)return toast('Use a distinct, nonempty name for each stage.');await mutate('save_settings',{config:c},'Stage names saved; record history retained.')});
 $('#field-settings')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target),label=String(f.get('label')).trim(),key=label.toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'');if(!key)return toast('Use letters or numbers in the field name.');if(data.config.fields.some(x=>x.key===key))return toast('A field with this name already exists.');const c=structuredClone(data.config);c.fields.push({key,label,type:f.get('type')});await mutate('save_settings',{config:c},'Custom field added to enquiry details.')});
 $('#brand-settings')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target),c=structuredClone(data.config);c.brand={name:String(f.get('name')).trim(),primary:f.get('primary'),accent:f.get('accent')};await mutate('save_settings',{config:c},'Workspace appearance saved.')});
 $('#ai-settings')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target),c=structuredClone(data.config);c.ai_enabled=f.has('enabled');c.monthly_budget=Number(f.get('budget'));await mutate('save_settings',{config:c},'AI demonstration preferences saved. No provider connected.')});
}
function utility(title,html){const d=$('#utility');d.innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2><button type="button" data-close aria-label="Close dialog">Close</button></div><div class="dialog-content">${html}</div>`;$('[data-close]',d).onclick=()=>d.close();if(!d.open)d.showModal();return d;}
function openLead(id){
 const requested=data.leads.find(l=>l.id===id);if(!requested)return;
 selected=id;mobileDetail=true;tableMode=false;
 if(!['enquiries','pipeline','work'].includes(page))page='enquiries';
 // A deliberate record action wins over incompatible browsing filters.
 // Otherwise splitWorkspace would silently select the first filtered record.
 if(branch&&requested.branch_id!==branch)branch='';
 if(stage&&requested.stage_id!==stage)stage='';
 if(ownerFilter&&requested.assigned_user_id!==ownerFilter)ownerFilter='';
 if(search&&![requested.name,requested.company,requested.email,requested.id,requested.property?.city].join(' ').toLowerCase().includes(search.toLowerCase()))search='';
 if(page==='pipeline')pipelineStage=requested.stage_id;
 render();if(innerWidth<=720)$('#record-workspace')?.scrollIntoView({block:'start'});
}
function bindRoleWorkspace(){
 $('#pipeline-branch')?.addEventListener('change',e=>{branch=e.target.value;selected=null;mobileDetail=false;render()});
 $$('[data-assign]').forEach(b=>b.onclick=()=>transferDialog(data.leads.find(l=>l.id===b.dataset.assign)));
 $$('[data-location]').forEach(b=>b.onclick=()=>{branch=b.dataset.location;stage='';search='';ownerFilter='';page='enquiries';selected=null;render()});
 $$('[data-owner-queue]').forEach(b=>b.onclick=()=>{ownerFilter=b.dataset.ownerQueue;page='enquiries';selected=null;branch='';stage='';search='';render()});
 $('#clear-owner')?.addEventListener('click',()=>{ownerFilter='';render()});
 $('#toggle-table')?.addEventListener('click',()=>{tableMode=!tableMode;mobileDetail=false;render()});
 $$('[data-stage]').forEach(b=>b.onclick=()=>{pipelineStage=b.dataset.stage;selected=null;mobileDetail=false;render()});
 $$('[data-pipeline-stage]').forEach(b=>b.onclick=()=>{page='pipeline';pipelineStage=b.dataset.pipelineStage;selected=null;branch='';mobileDetail=false;render()});
 $$('[data-work-tab]').forEach(b=>b.onclick=()=>{workTab=b.dataset.workTab;selected=null;mobileDetail=false;render()});
}
function enhanceRecord(l){
 const root=$('#record-workspace'),main=$('.detail-main',root),requirement=main.children[0],activity=main.children[1],history=main.children[2];
 const details=document.createElement('details');details.className='requirement-details';details.innerHTML='<summary>Requirement & custom fields <span>Review / edit</span></summary>';details.append(requirement);
 main.prepend(activity);main.insertBefore(details,history);
 const historyDetails=document.createElement('details');historyDetails.className='history-details';historyDetails.open=true;historyDetails.innerHTML=`<summary>Activity history <span>${(l.history||[]).length} recorded</span></summary>`;historyDetails.append(history);main.append(historyDetails);
 const context=document.createElement('div');context.className='record-context';context.innerHTML=`<div><span class="muted">Responsible</span><strong>${esc(userName(l.assigned_user_id))}</strong><small>${esc(branchName(l.branch_id))}</small>${manager()?'<button id="record-assign">'+(l.assigned_user_id?'Transfer ownership':'Assign owner')+'</button>':''}</div><div><span class="muted">Next action</span><strong>${esc(l.next_action||'Not recorded')}</strong><small class="${overdue(l)?'due':''}">${datetime(l.next_action_at)}</small></div>`;
 $('.dialog-head',root).after(context);$('#record-assign')?.addEventListener('click',()=>transferDialog(l));
 const review=document.createElement('section');review.className='stage-review';const missing=evidence(l);
 review.innerHTML=`<div class="section-title"><h3>Stage & information to confirm</h3>${badge(l)}</div><div class="evidence-list">${missing.length?missing.map(x=>`<span>${esc(x)}</span>`).join(''):'<span class="evidence-known">Bill, roof and proposed capacity are recorded; suitability still requires review.</span>'}</div><p class="stage-caveat">These are record checks, not an agreed business qualification policy or proof of a completed survey.</p><form id="stage-action"><div class="stage-action-fields"><label>Move to stage<select name="stage_id">${data.config.stages.map(s=>`<option value="${esc(s.id)}" ${s.id===l.stage_id?'selected':''}>${esc(s.label)}</option>`).join('')}</select></label><label>Evidence or reason<input name="evidence" maxlength="500" placeholder="What supports this change?" required></label><button type="submit">Update stage</button></div></form>`;
 if(page==='pipeline')main.prepend(review);else main.insertBefore(review,details);
 $('#stage-action').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);if(f.get('stage_id')===l.stage_id)return toast('Choose a different stage to record a transition.');const label=data.config.stages.find(s=>s.id===f.get('stage_id'))?.label;const note=`Stage review → ${label}: ${String(f.get('evidence')).trim()}`;const ok=await mutate('save_lead',{lead_id:l.id,version:l.version,changes:{stage_id:f.get('stage_id'),notes:[l.notes,note].filter(Boolean).join('\n\n')}},'Stage updated; reason retained in requirement notes and transition recorded.');if(ok&&page==='pipeline'){pipelineStage=f.get('stage_id');selected=l.id;render()}};
 if(isSales())$('.detail-aside .detail-section:first-child button',root)?.remove();
}

function renderRecord(id){const l=data.leads.find(x=>x.id===id);if(!l)return;selected=id;const d=$('#record-workspace'),prop=l.property||{};if(!d)return;d.innerHTML=`<div class="dialog-head"><div><h2 style="font-size:23px">${esc(l.name)}</h2><p class="muted" style="font-size:11px;margin-top:8px">${esc(l.id)} · ${esc(l.segment)} · Fictional enquiry</p><p>${esc(l.company||'Residential rooftop enquiry')} · ${esc(prop.city||'City unknown')}</p></div><button type="button" id="close-detail" class="back-to-queue">Back to queue</button></div><div class="detail-body"><div class="detail-main"><section class="detail-section"><div class="section-title"><h3>Enquiry & requirement</h3>${badge(l)}</div><form id="lead-form"><div class="form-grid"><label>Stage<select name="stage_id">${data.config.stages.map(s=>`<option value="${esc(s.id)}" ${s.id===l.stage_id?'selected':''}>${esc(s.label)}</option>`).join('')}</select></label><label>Proposed capacity · kW<input name="capacity_kw" type="number" min="0" step="0.1" placeholder="Unknown" value="${esc(prop.capacity_kw)}"></label><label>Monthly electricity bill · ₹<input name="bill" type="number" min="0" placeholder="Unknown" value="${esc(prop.bill)}"></label><label>Usable roof area · m²<input name="roof_area" type="number" min="0" step="0.1" placeholder="Unknown" value="${esc(prop.roof_area)}"></label><label class="wide">Requirement notes<textarea name="notes" maxlength="5000">${esc(l.notes)}</textarea></label><label class="wide">Recorded quotation value · ₹<input name="quote_value" type="number" min="0" value="${esc(l.quote_value)}" placeholder="Not recorded"></label>${data.config.fields.map(f=>`<label>${esc(f.label)}<input name="custom_${esc(f.key)}" type="${f.type==='number'?'number':'text'}" value="${esc(l.custom?.[f.key])}" maxlength="500"></label>`).join('')}</div><div class="form-actions"><button class="primary" type="submit">Save enquiry</button><small class="muted">Version ${l.version}</small></div></form></section><section class="detail-section"><h3>Log a conversation & next action</h3><form id="activity-form"><div class="form-grid"><label>Activity type<select name="type"><option value="call_connected">Call · connected</option><option value="call_no_answer">Call · no answer</option><option value="note">Internal note</option><option value="site_visit">Site visit note</option></select></label><label>Next follow-up<input name="next_action_at" type="datetime-local" value="${localDate(l.next_action_at)}"></label><label class="wide">What happened?<textarea name="text" required placeholder="Record the outcome; keep assumptions explicit." maxlength="5000"></textarea></label><label class="wide">Next action<input name="next_action" value="${esc(l.next_action)}" maxlength="300" placeholder="What should happen next?"></label></div><div class="form-actions"><button type="submit">Save activity & follow-up</button></div></form></section><section class="detail-section"><h3>Activity history</h3><ol class="history">${[...(l.history||[])].sort((a,b)=>b.at.localeCompare(a.at)).map(h=>`<li>${esc(h.text)}<small>${esc(h.by)} · ${datetime(h.at)}</small></li>`).join('')||'<li>No recorded activity yet</li>'}</ol></section></div><aside class="detail-aside"><section class="detail-section"><h3>Responsibility</h3><div class="person"><span class="avatar">${esc(initials(userName(l.assigned_user_id)))}</span><div><strong style="font-size:13px">${esc(userName(l.assigned_user_id))}</strong><small style="display:block;color:var(--muted);margin-top:5px">${esc(branchName(l.branch_id))}</small></div></div>${manager()?'<button id="transfer" style="margin-top:15px">Transfer ownership</button>':''}</section><section class="detail-section"><h3>Contact & source</h3><div class="meta-row"><span class="muted">Email</span><span>${esc(l.email||'Not recorded')}</span></div><div class="meta-row"><span class="muted">Phone</span><span>${esc(l.phone||'Not recorded')}</span></div><div class="meta-row"><span class="muted">Source</span><span>${esc(l.source)}</span></div><div class="meta-row"><span class="muted">Received</span><span>${date(l.created_at)}</span></div><p class="muted" style="font-size:11px;margin-top:13px">Sample contacts are not dialable. No email, call or message is sent from this showcase.</p></section>${data.config.ai_enabled?`<section class="ai-box"><h3>AI enabled <span class="badge orange">Demo · not connected</span></h3><p>Preview a reviewable assistant draft for this enquiry.</p><button id="ai-preview">Preview AI draft</button><div id="ai-result"></div></section>`:`<p class="notice">AI assistance is off. All enquiry and follow-up tools remain available.</p>`}</aside></div>`;$('#close-detail').onclick=()=>{mobileDetail=false;render()};enhanceRecord(l);$('#lead-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),number=k=>f.get(k)===''?null:Number(f.get(k)),custom={...l.custom};data.config.fields.forEach(x=>custom[x.key]=x.type==='number'?number('custom_'+x.key):f.get('custom_'+x.key));const changes={notes:f.get('notes'),property:{...prop,bill:number('bill'),roof_area:number('roof_area'),capacity_kw:number('capacity_kw')},quote_value:number('quote_value'),custom};if(f.get('stage_id')!==l.stage_id)changes.stage_id=f.get('stage_id');await mutate('save_lead',{lead_id:l.id,version:l.version,changes},'Enquiry saved.')};$('#activity-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);await mutate('add_activity',{lead_id:l.id,version:l.version,type:f.get('type'),text:f.get('text'),next_action:f.get('next_action'),next_action_at:f.get('next_action_at')?new Date(f.get('next_action_at')).toISOString():null},'Activity and next action saved.')};$('#transfer')?.addEventListener('click',()=>transferDialog(l));$('#ai-preview')?.addEventListener('click',()=>aiDraft(l));}
function transferDialog(l){const branches=data.branches.filter(b=>data.user.role==='central_manager'||data.user.branches.includes(b.id));const d=utility('Transfer ownership',`<p>Keep responsibility clear and preserve the reason in the enquiry history.</p><form id="transfer-form"><div class="form-grid"><label>Handling location<select name="branch_id" id="target-branch">${branches.map(b=>`<option value="${esc(b.id)}" ${b.id===l.branch_id?'selected':''}>${esc(b.name)}</option>`).join('')}</select></label><label>New owner<select name="assigned_user_id" id="target-user"></select></label><label class="wide">Transfer reason<textarea name="reason" required maxlength="500" placeholder="Why is responsibility changing?"></textarea></label></div><div class="form-actions"><button class="primary" type="submit">Confirm transfer</button></div></form>`);const fill=()=>{$('#target-user').innerHTML=data.users.filter(u=>u.role==='salesperson'&&u.active!==false&&u.branches.includes($('#target-branch').value)).map(u=>`<option value="${esc(u.id)}">${esc(u.name)}</option>`).join('')};fill();$('#target-branch').onchange=fill;$('#transfer-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);if(await mutate('assign_lead',{lead_id:l.id,version:l.version,assigned_user_id:f.get('assigned_user_id'),branch_id:f.get('branch_id'),reason:f.get('reason')},'Ownership transferred with history.'))d.close()};}
function aiDraft(l){const known=[l.property?.bill,l.property?.roof_area,l.property?.capacity_kw].filter(v=>v!=null).length;const text=`Draft from recorded information: ${l.name} is exploring ${l.segment.toLowerCase()} rooftop solar in ${l.property?.city||'an unconfirmed city'}. ${l.property?.capacity_kw?l.property.capacity_kw+' kW is recorded as proposed capacity.':'Proposed capacity is unknown.'} Next: confirm electricity bill, usable roof and decision-maker before recommending a system.`;$('#ai-result').innerHTML=`<p><strong>Requirement summary · illustrative draft</strong></p><p>${esc(text)}</p><p><strong>Information readiness: ${known}/3</strong><br>Bill, roof area and capacity recorded. This is a deterministic completeness check, not a probability of winning.</p>${l.segment==='Commercial'?'<p><strong>Company research opportunity</strong><br>An assistant could check company/site context with approved sources. No websites were researched; no external facts or citations are asserted.</p>':''}<p class="muted">Illustrative run estimate: 1,200 input + 250 output tokens. Actual usage: 0; no model connected. Cost depends on provider and approved rates.</p><div class="actions"><button id="accept-ai">Accept as draft note</button><button id="discard-ai">Discard</button></div>`;$('#accept-ai').onclick=async()=>{await mutate('add_activity',{lead_id:l.id,version:l.version,type:'ai_demo_draft',text:'DEMO AI draft accepted for review — '+text},'Demo draft added to history; factual fields unchanged.')};$('#discard-ai').onclick=()=>{$('#ai-result').innerHTML='';toast('Draft discarded. Enquiry unchanged.')};}
function importDialog(){const demoRow={name:'Willow Studio · sample',company:'Willow Studio',email:'willow@example.com',phone:'DEMO-PHONE-IMPORT',segment:'Commercial',branch_id:data.user.branches[0]||data.branches[0].id,assigned_user_id:null,stage_id:data.config.stages[0].id,source:'Facebook · sample',account_id:'DEMO-PAGE',form_id:'DEMO-FORM',submission_id:'DEMO-SUBMISSION-001',property:{city:'Gurugram',address:'Fictional property',bill:null,roof_area:null,capacity_kw:null},notes:'Fictional sample to demonstrate repeat-import handling.',next_action:'Assign an owner and make first contact',next_action_at:null,quote_value:null,custom:{}};const d=utility('Preview sample import',`<p>One fictional source submission. Importing it again should recognise the same submission.</p><div class="notice">Source: DEMO-PAGE / DEMO-FORM<br>Submission: DEMO-SUBMISSION-001</div><div class="meta-row"><strong>Willow Studio · sample</strong><span>Commercial</span></div><p class="muted">1 row ready · bill, roof and capacity unknown · owner unassigned.<br>No connection to Facebook is made.</p><button class="primary" id="confirm-import">Import this sample</button>`);$('#confirm-import').onclick=async()=>{if(await mutate('import_rows',{rows:[demoRow]},null))d.close()};}
function userDialog(){const d=utility('Add a demo user',`<p>Create a fictional sales account for this workspace. This adds a demo view, not a real login.</p><form id="user-form"><div class="form-grid"><label class="wide">Display name<input name="name" required maxlength="60" placeholder="Demo colleague"></label><label>Role<select name="role"><option value="salesperson">Salesperson</option><option value="branch_manager">Branch manager</option></select></label><label>Location<select name="branch">${data.branches.map(b=>`<option value="${esc(b.id)}">${esc(b.name)}</option>`).join('')}</select></label></div><div class="form-actions"><button class="primary" type="submit">Create demo user</button></div></form>`);$('#user-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);if(await mutate('create_user',{user:{name:f.get('name'),role:f.get('role'),branches:[f.get('branch')]}},'Demo user created.'))d.close()};}
function resetDialog(){const d=utility('Reset this browser’s demo?',`<p>This removes your local edits, added users, stage names and custom fields. The original fictional sample will return. Saved preferences will also reset.</p><button class="danger" id="confirm-reset">Reset fictional dataset</button>`);$('#confirm-reset').onclick=()=>{db=structuredClone(seed);actorId='central';prefs={compact:false,view:null};persist();savePrefs();data=snapshot();branch='';stage='';search='';selected=null;page='overview';ownerFilter='';mobileDetail=false;d.close();$('#detail').close();render();toast(Object.values(storageIssues).some(Boolean)?'Fictional dataset reset for this session only. Browser storage could not save it.':'Original fictional dataset restored.')};}
function help(){utility('A five-minute showcase',`<p>All people, enquiries and desk locations are fictional. This demonstration shows a configurable workflow; your actual rules would follow discovery.</p><ol><li>Switch between Aditi’s business oversight, Kabir’s branch coordination and Neha/Rohan’s working day. These are four fictional accounts across three roles.</li><li>In the split workspace, select an enquiry and log a call with a next follow-up. Requirement and history remain beside the queue, without a detail modal.</li><li>As a manager, assign an unowned enquiry with a reason. In Pipeline, choose a stage and review the selected record’s missing information before updating it. Switch the <strong>Demo view</strong> to Neha or Rohan to illustrate their record scope.</li><li>Open <strong>Settings</strong>: rename a stage, add “Roof ownership” and change the workspace appearance.</li><li>Preview an AI draft, accept it as a clearly marked note or discard it. No provider is connected.</li></ol><p><span class="help-key">Esc</span> closes a dialog. <span class="help-key">/</span> focuses enquiry search. <span class="help-key">?</span> opens this guide.</p><p class="muted">Changes persist in this browser when local storage is available. Another browser starts a fresh fictional dataset. Local role switching is illustrative, not authentication. Use Settings → Reset to start again.</p>`)}
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))return;if(e.key==='?'&&!$('#utility').open){e.preventDefault();help()}if(e.key==='/'&&!$('#detail').open&&!$('#utility').open){e.preventDefault();page='enquiries';render();$('#search').focus()}});

(async()=>{try{data=await api('bootstrap');if(!prefs.views){prefs.views={};if(prefs.view){prefs.views[data.user.id]=prefs.view;savePrefs();}}prefs.view=prefs.views[data.user.id]||null;workspaceReset();render()}catch(e){$('#app').innerHTML=`<div class="loading"><h1>Workspace unavailable</h1><p style="margin:16px 0">${esc(e.message)}</p><button onclick="location.reload()">Try again</button></div>`}})();
})();
